package ru.innopolis.runtime;

import java.util.HashMap;
import java.util.Map;

/**
 * In-memory ClassLoader that loads dynamically generated bytecode without saving to disk.
 * Part of Person 1 & Person 3 runtime execution support.
 */
public class BytecodeClassLoader extends ClassLoader {
    private final Map<String, byte[]> classes = new HashMap<>();

    public BytecodeClassLoader(ClassLoader parent) {
        super(parent);
    }

    public BytecodeClassLoader() {
        this(BytecodeClassLoader.class.getClassLoader());
    }

    public void addClass(String internalName, byte[] bytecode) {
        String binaryName = internalName.replace('/', '.');
        classes.put(binaryName, bytecode);
    }

    public void addClasses(Map<String, byte[]> generatedClasses) {
        for (Map.Entry<String, byte[]> entry : generatedClasses.entrySet()) {
            addClass(entry.getKey(), entry.getValue());
        }
    }

    public void runMain(String className, String... arguments) throws ReflectiveOperationException {
        loadClass(className.replace('/', '.')).getMethod("main", String[].class).invoke(null, (Object) arguments);
    }

    @Override
    protected synchronized Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
        if (!classes.containsKey(name)) return super.loadClass(name, resolve);
        Class<?> loaded = findLoadedClass(name);
        if (loaded == null) loaded = findClass(name);
        if (resolve) resolveClass(loaded);
        return loaded;
    }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        byte[] bytes = classes.get(name);
        if (bytes != null) {
            return defineClass(name, bytes, 0, bytes.length);
        }
        return super.findClass(name);
    }
}
